def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, 35.0))
        return float(min(budget, 18.0))

    prev_bids = []
    opp_pressure = 0.0
    rich_alive = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > 0:
            rich_alive += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid > opp_pressure:
                    opp_pressure = float(bid)

    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        max_prev = max(prev_bids)
    else:
        avg_prev = 80.0
        max_prev = 100.0

    total_alive = 1 + len(alive_opponents)
    units = int(supply // WATER_REQ)
    scarcity = units < total_alive
    very_tight = units <= 1

    if hp <= 2 or no_water_days >= 2:
        bid = max(150.0, max_prev + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        if very_tight:
            bid = max(140.0, avg_prev + 8.0)
        elif scarcity:
            bid = max(118.0, avg_prev + 2.0)
        else:
            bid = 72.0
    else:
        if very_tight:
            bid = max(132.0, avg_prev + 4.0)
        elif scarcity:
            bid = 58.0
        else:
            bid = 22.0

    if rich_alive == 1 and hp > 4 and no_water_days == 0:
        bid = min(bid, 45.0)

    if day >= 8:
        if hp <= 5:
            bid = max(bid, 110.0)
        else:
            bid = max(bid, 40.0)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents alive, bid minimal to conserve.
    if not alive_opps:
        bid = DAILY_SALARY * 0.25
        if budget < bid:
            return max(0.0, budget)
        return bid

    # Read yesterday bids from immediate previous_trace only.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine urgency from our HP and no-water streak.
    urgency = 0
    if hp <= 2.0:
        urgency += 2
    if hp <= 4.0:
        urgency += 1
    if no_water_days >= 2:
        urgency += 1

    # Supply pressure: if supply is low, competition is higher; raise bid slightly.
    # Use a conservative scale; avoid matching Cindy/Eric bids unless necessary.
    if supply <= 17.0:
        supply_factor = 1.15
    elif supply <= 21.0:
        supply_factor = 1.05
    else:
        supply_factor = 0.95

    # Baseline bid: aim around half salary to win occasionally without burning budget.
    # If yesterday aggressors bid extremely high, we still avoid overbidding unless urgency is high.
    aggressive_threshold = DAILY_SALARY * 1.2  # ~108

    if urgency >= 2:
        # High urgency: bid closer to aggressive level but cap.
        target = max(DAILY_SALARY * 0.75, highest_prev_bid * 0.65)
    elif urgency == 1:
        target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.45)
    else:
        # Low urgency: do not chase; bid just enough.
        if highest_prev_bid >= aggressive_threshold:
            target = DAILY_SALARY * 0.40
        else:
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.30)

    target *= supply_factor

    # Ensure we don't bid more than we can afford; keep non-negative.
    if budget <= 0.0:
        return 0.0

    if target > budget:
        target = budget

    # Also avoid bidding too low when supply is scarce and we need water to prevent death.
    # If we've already had 1+ no-water days, increase floor.
    min_floor = 0.0
    if no_water_days >= 1:
        min_floor = DAILY_SALARY * 0.35
    if hp <= 4.0:
        min_floor = max(min_floor, DAILY_SALARY * 0.5)

    if target < min_floor:
        target = min_floor
        if target > budget:
            target = budget

    return max(0.0, float(target))

